"""CLI driver: generate dark profile cards from the snapshot API."""

import argparse
import json
import sys
import urllib.request
from datetime import UTC, datetime
from pathlib import Path
from types import SimpleNamespace

from .builders import CARDS, build_unavailable
from .network import UA
from .theme import FULL_W, HALF_W

API_URL = "https://spreadsheets600-api.spreadsheets600.workers.dev/snapshot"

README_SNIPPET = """<!-- cards: generated by generate_cards.py -->
<div align="center">
<img src="cards/profile.svg" width="100%" alt="GitHub profile" />
<br/><br/>
<img src="cards/stats.svg" width="49%" alt="GitHub stats" /><img src="cards/streak.svg" width="49%" alt="Streak" />
<br/><br/>
<img src="cards/activity.svg" width="100%" alt="Contribution activity" />
<br/><br/>
<img src="cards/languages.svg" width="49%" alt="Languages" /><img src="cards/wakatime.svg" width="49%" alt="Coding time" />
<br/><br/>
<img src="cards/repos.svg" width="100%" alt="Top repositories" />
<br/><br/>
<img src="cards/steam.svg" width="100%" alt="Steam" />
<br/><br/>
<img src="cards/spotify.svg" width="49%" alt="Spotify" /><img src="cards/anilist.svg" width="49%" alt="AniList" />
</div>
"""


def load(args):
    if args.input:
        return json.loads(Path(args.input).read_text(encoding="utf-8"))
    req = urllib.request.Request(
        args.url, headers={"User-Agent": UA, "Accept": "application/json"}
    )
    with urllib.request.urlopen(req, timeout=60) as r:
        return json.loads(r.read().decode("utf-8"))


def main(argv=None):
    ap = argparse.ArgumentParser(
        description="Generate dark profile cards from the snapshot API"
    )
    ap.add_argument("--url", default=API_URL)
    ap.add_argument("--input", help="read a saved snapshot JSON instead of calling the API")
    ap.add_argument("--out", help="output folder (default: ./cards/output next to this script)")
    ap.add_argument(
        "--only", nargs="*", help="only these cards, e.g. --only steam stats"
    )
    args = ap.parse_args(argv)

    try:
        data = load(args)
    except Exception as e:
        print(f"fatal: could not load snapshot: {e}", file=sys.stderr)
        return 1

    gen = parse_dt_safe(data.get("generatedAt")) or datetime.now(UTC)
    ctx = SimpleNamespace(now=gen)

    default_out = Path(__file__).resolve().parent / "output"
    out = Path(args.out) if args.out else default_out
    out.mkdir(parents=True, exist_ok=True)

    for name, source, builder, ico in CARDS:
        if args.only and name not in args.only:
            continue
        target = out / f"{name}.svg"
        sec = data.get(source) or {}
        try:
            if not sec.get("ok") or sec.get("data") is None:
                if target.exists():
                    print(
                        f"= {name}: source '{source}' not ok ({sec.get('error')}), keeping previous card"
                    )
                    continue
                svg = build_unavailable(source.capitalize(), sec.get("error"), ctx, ico)
                print(
                    f"~ {name}: source '{source}' not ok ({sec.get('error')}), wrote placeholder"
                )
            else:
                svg = builder(sec["data"], ctx)
                print(f"+ {name}: {len(svg) / 1024:.0f} KB")
            target.write_text(svg, encoding="utf-8")
        except Exception as e:  # keep going, old file stays untouched
            print(f"! {name}: failed ({e.__class__.__name__}: {e})", file=sys.stderr)

    (out / "README.cards.md").write_text(README_SNIPPET, encoding="utf-8")
    print(f"done -> {out.resolve()}")
    return 0


def parse_dt_safe(s):
    from .util import parse_dt

    return parse_dt(s)


if __name__ == "__main__":
    sys.exit(main())
